func Or(predicates ...predicate.SessionTurn) predicate.SessionTurn {
	return predicate.SessionTurn(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SessionTurn) predicate.SessionTurn {
	return predicate.SessionTurn(sql.NotPredicates(p))
}
